import re
import time
import datetime


class L2CPUParser(object):
    def __init__(self, input_log):
        """
        :param  input_log: log file to parse
        """
        self.log = input_log
        self.data = {'Timestamps': [],
                     'CPU_per_disp': {},
                     'CPU_per_measurement': {}}

    def parse(self):
        """
        method start the parsing process
        :return:
        """
        try:
            with open(self.log) as input_log:
                for line in input_log:
                    self._analyze_timestamp(line)
                    self._analyze_cpu_data(line)
        except IOError:
            print("L2_CPU_Parser: Unable to open file " + str(self.log) + " or file doesn't exist")  # noqa: T201

    def get(self, data_type):
        """
        :param data_type: define which data you want to get
        :return: properly data from self.data of L2CPUParser
        """
        return self.data.get(data_type)

    @staticmethod
    def parse_timestamp(timestamp):
        """
        :param timestamp: time in format <2019-01-11T07:35:35.000566Z>
        :return: unix time of passed param
        """
        try:
            return time.mktime(datetime.datetime((int(str(str(timestamp.group(1))))), int(timestamp.group(2)),
                                                 int(timestamp.group(3)), int(timestamp.group(4)),
                                                 int(timestamp.group(5)), int(timestamp.group(6))).timetuple())
        except IndexError:
            return -1

    def _analyze_timestamp(self, line):
        self._timestamp_flag = True
        _timestamp = re.match(r"Timestamp: \<(\d+)-(\d+)-(\d+)T(\d+):(\d+):(\d+).*.\>", line)
        if _timestamp is not None:
            self.data['Timestamps'].append(L2CPUParser.parse_timestamp(_timestamp))

    def _analyze_cpu_data(self, line):
        try:
            if self._timestamp_flag is True:
                cpu_data = re.split(r",", line.replace('%', '').strip())[0:]
                self._assign_cpu_measurements_parameters(cpu_data)
                if re.match(r"\d+", cpu_data[0]):
                    self._add_cpu_data(cpu_data)
        except (IndexError, KeyError):
            print("L2_CPU_Parser: Unable to analyze L2 CPU measurements")  # noqa: T201

    def _assign_cpu_measurements_parameters(self, cpu_data):
        if "Disp" in cpu_data:
            self.parameters = cpu_data[1:]

    def _add_cpu_data(self, cpu_data):
        try:
            self._add_cpu_data_per_disp(cpu_data)
            self._add_cpu_data_per_measurement(cpu_data)
        except (KeyError, IndexError):
            print("L2_CPU_Parser: Unable to analyze L2 CPU measurements")  # noqa: T201

    def _add_cpu_data_per_disp(self, cpu_data):
        if "Disp_{}".format(cpu_data[0]) not in self.data['CPU_per_disp']:
            self.data['CPU_per_disp']["Disp_{}".format(cpu_data[0])] = {}
            for parameter in self.parameters:
                self.data['CPU_per_disp']["Disp_{}".format(cpu_data[0])].update({parameter.strip(): []})
        if "Disp_{}".format(cpu_data[0]) in self.data['CPU_per_disp']:
            for index, parameter in enumerate(self.parameters):
                self.data['CPU_per_disp']["Disp_{}".format(cpu_data[0])][parameter.strip()].\
                    append(cpu_data[index + 1].strip())

    def _add_cpu_data_per_measurement(self, cpu_data):
        for index, parameter in enumerate(self.parameters):
            if parameter.strip() not in self.data['CPU_per_measurement']:
                self.data['CPU_per_measurement'][parameter.strip()] = {}
            if parameter.strip() in self.data['CPU_per_measurement']:
                if "Disp_{}".format(cpu_data[0]) not in self.data['CPU_per_measurement'][parameter.strip()]:
                    self.data['CPU_per_measurement'][parameter.strip()]["Disp_{}".format(cpu_data[0])] = []
                if "Disp_{}".format(cpu_data[0]) in self.data['CPU_per_measurement'][parameter.strip()]:
                    self.data['CPU_per_measurement'][parameter.strip()]["Disp_{}".format(cpu_data[0])].append(
                        cpu_data[index + 1].strip())


